"use strict";const t={API_BASE:"http://8.215.108.239/api",IMAGE_BASE:"http://8.215.108.239"};exports.CONFIG=t,exports.getImageUrl=s=>{if(!s)return"";if("string"==typeof s&&(s.includes("192.168.")||s.includes("localhost")||s.includes("127.0.0.1"))){const r=s.match(/(\/uploads\/.*)$/);if(r)return`${t.IMAGE_BASE}/api${r[1]}`}if(s.startsWith("http")||s.startsWith("data:"))return s;if(s.startsWith("/api"))return`${t.IMAGE_BASE}${s}`;const r=s.replace(/^\//,"");return r.startsWith("uploads/")?`${t.IMAGE_BASE}/api/${r}`:`${t.IMAGE_BASE}/${r}`};
